function parseCSV(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){cell+='"';i++}else q=!q}else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()!==''))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()!==''))rows.push(row);if(!rows.length)return[];const h=rows[0].map(x=>x.trim().toLowerCase());return rows.slice(1).map(r=>Object.fromEntries(h.map((k,i)=>[k,(r[i]??'').trim()])))}
function jsonArray(s){try{return JSON.parse(s)}catch{return[]}}
// Rule-based demo scorer removed: all displayed risk scores come from the offline Isolation Forest.
function stats(rows){return{transactions:rows.length,high:rows.filter(x=>x.severity==='High').length,medium:rows.filter(x=>x.severity==='Medium').length,low:rows.filter(x=>x.severity==='Low').length,ips:new Set(rows.map(x=>x.ip)).size,flagged:rows.filter(x=>x.anomaly>=40).length}}

function signalMeta(r){const p=String(r.synthetic_pattern||'normal').toLowerCase();const map={normal:['Normal activity','No elevated behavioral pattern detected','Baseline behavior'],moderate_fan_in_fan_out:['Fan-in / fan-out','Multiple inputs or outputs suggest aggregation or distribution behavior','Flow topology'],moderate_ip_reuse:['IP reuse','Broadcast infrastructure appears across related activity','Infrastructure correlation'],rapid_forwarding:['Rapid forwarding','Funds appear to move through the network quickly','Velocity pattern'],high_rapid_peeling_chain:['Peeling chain','Repeated forwarding creates a chain-like movement pattern','Topology + velocity'],high_mixing_pattern:['Mixing pattern','Transaction structure resembles a mixing / obfuscation pattern','Topology + amount flow'],high_ip_reuse_fanout:['IP reuse + fan-out','Repeated infrastructure combined with broad output fan-out','Infrastructure + topology']};const x=map[p]||[p.replace(/_/g,' '),'Dataset-provided risk signal','Synthetic pattern'];return{label:x[0],desc:x[1],basis:x[2]}}
async function loadCsvText(text,name){
  if(typeof text!=='string'||!text.trim()) throw new Error('Empty CSV');
  const records=parseCSV(text);
  if(!records.length) throw new Error('No CSV rows found');
  const required=['timestamp','src_ip','dst_ip','src_port','dst_port','txid','input_addresses','output_addresses','input_amounts','output_amounts','fee','script_type'];
  const missing=required.filter(k=>!(k in records[0]));
  if(missing.length) throw new Error('Missing required columns: '+missing.join(', '));
  const rows=rowsFromDataset(records);
  if(!rows.length) throw new Error('No valid transactions found');
  if(!window.location.protocol.startsWith('http')) throw new Error('Open with Vercel or `vercel dev` so the real Python ML API is available.');
  const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({records})});
  const payload=await response.json().catch(()=>({}));
  if(!response.ok || !payload.ok) throw new Error(payload.detail || payload.error || 'ML API analysis failed');
  const scored=new Map((payload.rows||[]).map(r=>[String(r.txid),r]));
  rows.forEach(r=>{const m=scored.get(String(r.txid)); if(m) Object.assign(r,m);});
  applyMLResults(rows);
  window.__coinTraceMLMeta=payload.model;
  state.rows=rows;
  state.stats=stats(rows);
  state.datasetName=name||'Imported Dataset';
  state.section='Overview';
  state.query='';
  state.graphQuery='';
  render();
  return rows;
}
function rowsFromDataset(records){return records.map((r,i)=>{const ins=jsonArray(r.input_addresses),outs=jsonArray(r.output_addresses),oa=jsonArray(r.output_amounts).map(Number),ia=jsonArray(r.input_amounts).map(Number);const amount=oa.reduce((a,b)=>a+b,0)||ia.reduce((a,b)=>a+b,0);return{txid:r.txid||'tx-'+String(i+1).padStart(6,'0'),wallet:ins[0]||outs[0]||'unknown-wallet-'+(i+1),wallets:[...ins,...outs],input_addresses:ins,output_addresses:outs,ip:r.src_ip||'0.0.0.0',dstIp:r.dst_ip||'',srcPort:r.src_port||'',dstPort:r.dst_port||'',amount,fee:Number(r.fee)||0,timestamp:r.timestamp||'',inputs:ins.length||1,outputs:outs.length||1,country:r.country||'Unknown',asn:r.asn||'Unknown',scriptType:r.script_type||'Unknown',anomaly:0,reason:'ML anomaly signal',signalDesc:'Generated from the multivariate Isolation Forest score.',signalBasis:'Offline ML feature space',pattern:'ML-derived',groundTruth:null,referenceScore:null,severity:'Low',riskScore:0}}).sort((a,b)=>a.txid.localeCompare(b.txid))}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function badge(s){return `<span class="badge ${s==='High'?'high':s==='Medium'?'med':'low'}">${s}</span>`}
function table(rows){if(!rows.length)return'<div class="empty">No transactions found.</div>';return `<div class="tablewrap"><table class="table"><thead><tr><th>TXID</th><th>Wallet</th><th>Broadcast IP</th><th>Amount</th><th>Risk</th><th>Severity</th><th>Signal</th></tr></thead><tbody>${rows.map(r=>`<tr class="tx-row" data-tx-index="${state.rows.indexOf(r)}"><td class="mono">${esc(r.txid)}</td><td class="mono">${esc(r.wallet)}</td><td class="mono">${esc(r.ip)}</td><td>${Number(r.amount).toFixed(3)} BTC</td><td class="score">${r.anomaly}</td><td>${badge(r.severity)}</td><td><span class="signal signal-${r.severity==='High'?'high':r.severity==='Medium'?'med':'low'}"><i class="signal-dot"></i>${esc(r.reason)}</span><div class="signal-desc">${esc(r.signalDesc||'Dataset-provided signal')}</div></td></tr>`).join('')}</tbody></table></div>`}
function graphData(){
  const q=(state.graphQuery||'').toLowerCase();
  const risk=state.graphRisk||'All';
  let txs=state.rows.filter(r=>risk==='All'||r.severity===risk);
  if(q) txs=txs.filter(r=>(r.txid+' '+r.wallet+' '+r.ip+' '+r.country).toLowerCase().includes(q));
  txs=txs.sort((a,b)=>b.anomaly-a.anomaly).slice(0,Math.min(Math.max(Number(state.graphLimit||50),10),500));
  const nodes=[],edges=[],seen=new Set();
  const add=(id,type,label,riskScore,meta)=>{if(!seen.has(id)){seen.add(id);nodes.push({id,type,label,riskScore,meta})}};
  txs.forEach(r=>{
    const tid='t:'+r.txid; add(tid,'tx',r.txid,r.anomaly,r);
    const ip='ip:'+r.ip; add(ip,'ip',r.ip,r.anomaly,r);
    edges.push({a:ip,b:tid,risk:r.severity==='High',med:r.severity==='Medium'});
    const ins=jsonArray(r.input_addresses).length?jsonArray(r.input_addresses):(r.wallet?[r.wallet]:[]), outs=jsonArray(r.output_addresses);
    const wallets=[...ins.slice(0,1),...outs.slice(0,2)].filter(Boolean);
    wallets.forEach((w,wi)=>{
      const wid='w:'+w; add(wid,'wallet',w,r.anomaly,r);
      edges.push({a:tid,b:wid,risk:r.severity==='High',med:r.severity==='Medium',kind:wi===0?'input':'output'});
    });
  });
  return {nodes,edges,txs};
}
