  const openGraphHero=document.getElementById('openGraphHero'); if(openGraphHero) openGraphHero.onclick=()=>{state.section='Entity Graph';render()}; const openTxHero=document.getElementById('openTxHero'); if(openTxHero) openTxHero.onclick=()=>{state.section='Transactions';render()}; document.querySelectorAll('[data-section]').forEach(x=>x.onclick=()=>{state.section=x.dataset.section;render()}); document.querySelectorAll('.tx-row').forEach(x=>x.onclick=()=>openTxDetail(state.rows[Number(x.dataset.txIndex)]));
  const refresh=document.getElementById('refresh'); if(refresh) refresh.onclick=()=>render(); const runML=document.getElementById('runML'); if(runML) runML.onclick=runMLDemo;
