function buildHoldoutBenchmark(rows){
  const base=rows.slice(0,Math.min(120,rows.length)).map(r=>({...r,wallets:[...(r.wallets||[])],input_addresses:[...(r.input_addresses||[])],output_addresses:[...(r.output_addresses||[])],mlScore:0}));
  const normal=base.slice(0,Math.min(60,base.length)).map(r=>({...r,benchmarkLabel:0}));
  const anomalies=base.slice(60,Math.min(120,base.length)).map((r,i)=>{const x={...r,benchmarkLabel:1};
    if(i%3===0){x.amount=Math.max(5,(Number(x.amount)||0)*25);x.outputs=Math.max(8,x.outputs*4);}
    else if(i%3===1){x.inputs=Math.max(8,x.inputs*4);x.outputs=Math.max(6,x.outputs*3);x.fee=Math.max(0.01,(Number(x.fee)||0)*12);}
    else{x.ip='benchmark-shared-ip';x.wallet='benchmark-shared-wallet';x.wallets=['benchmark-shared-wallet'];x.inputs=Math.max(7,x.inputs*3);x.outputs=Math.max(7,x.outputs*3);}
    return x;
  });
  return normal.concat(anomalies);
}
function mlValidation(rows){
  if(rows.length<20)return null;
  const holdout=buildHoldoutBenchmark(rows); applyIsolationForest(holdout);
  const threshold=75;let tp=0,tn=0,fp=0,fn=0;
  for(const r of holdout){const pred=r.mlScore>=threshold,truth=r.benchmarkLabel===1;if(pred&&truth)tp++;else if(pred&&!truth)fp++;else if(!pred&&truth)fn++;else tn++;}
  const precision=tp/(tp+fp)||0,recall=tp/(tp+fn)||0,f1=2*precision*recall/(precision+recall)||0;
  const pos=holdout.filter(r=>r.benchmarkLabel===1),neg=holdout.filter(r=>r.benchmarkLabel===0);let wins=0;
  for(const p of pos)for(const n of neg){if(p.mlScore>n.mlScore)wins++;else if(p.mlScore===n.mlScore)wins+=.5;}
  const auc=pos.length&&neg.length?wins/(pos.length*neg.length):0;
  return{n:holdout.length,tp,tn,fp,fn,precision,recall,f1,auc,threshold,positive:pos.length,negative:neg.length};
}
function applyMLResults(rows){rows.forEach(r=>{r.referenceScore=r.referenceScore??null;r.riskScore=r.mlScore;r.anomaly=r.mlScore;r.severity=r.severity || (r.mlScore>=75?'High':r.mlScore>=40?'Medium':'Low');const f=r.mlFeatures||{};const clues=[];if((f.ipReuse||1)>=4)clues.push('IP reuse');if((r.outputs||1)>=4)clues.push('fan-out');if((r.inputs||1)>=4)clues.push('fan-in');if((f.walletReuse||1)>=4)clues.push('wallet reuse');if((f.amount||0)>=5)clues.push('large amount');r.reason=clues.length?`ML anomaly · ${clues.slice(0,2).join(' + ')}`:'ML anomaly score';r.signalDesc=r.mlExplanation;r.signalBasis='Isolation Forest feature space';r.pattern='ML-derived';});return rows}

function showDatasetPicker(){
  if(document.getElementById('datasetModal')) return;
  const modal=document.createElement('div'); modal.id='datasetModal'; modal.className='dataset-modal'; modal.innerHTML=`<div class="dataset-backdrop"></div><div class="dataset-dialog" role="dialog" aria-modal="true" aria-labelledby="datasetTitle"><button class="dataset-close" id="datasetClose" aria-label="Close">×</button><div class="dataset-kicker">DATA INGESTION</div><h2 id="datasetTitle">Import transaction data</h2><p>Choose how you want to load the investigation dataset.</p><div class="dataset-options"><button class="dataset-option" id="customCsv"><span class="dataset-icon">↑</span><span><b>Use your own CSV</b><small>Upload your transaction dataset</small></span><strong>→</strong></button><button class="dataset-option synthetic" id="syntheticCsv"><span class="dataset-icon">✦</span><span><b>Use Synthetic Dataset</b><small>Load the preinstalled SIH demo dataset</small></span><strong>→</strong></button></div><div class="dataset-note">Synthetic data is generated for demonstration purposes only.</div><input type="file" id="hiddenCsv" accept=".csv,text/csv" hidden></div>`;
  document.body.appendChild(modal);
  const close=()=>modal.remove(); document.getElementById('datasetClose').onclick=close; document.querySelector('.dataset-backdrop').onclick=close;
  const input=document.getElementById('hiddenCsv');
  document.getElementById('customCsv').onclick=()=>input.click();
  input.onchange=async e=>{const f=e.target.files[0];if(!f)return;close();try{const nameEl=document.getElementById('filename');if(nameEl)nameEl.textContent='Analyzing '+f.name+'…';await loadCsvText(await f.text(),f.name)}catch(err){const nameEl=document.getElementById('filename');if(nameEl)nameEl.textContent='Unable to read this CSV: '+(err.message||'invalid format')}};
  document.getElementById('syntheticCsv').onclick=async()=>{const b=document.getElementById('syntheticCsv');const small=b.querySelector('small');b.disabled=true;small.textContent='Loading demo dataset…';try{const text=PREINSTALLED_DATASET;if(!text)throw new Error('embedded dataset unavailable');await loadCsvText(text,'Synthetic Dataset · SIH 2026');small.textContent='Dataset ready · loaded locally';close()}catch(err){if(state.rows&&state.rows.length){small.textContent='Dataset ready · loaded locally';close()}else{b.disabled=false;small.textContent='Unable to load dataset';}}};
  document.addEventListener('keydown',function escModal(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',escModal)}});
}
state.rows=[]; state.stats=stats([]); render();
